def choose_move(observation):
    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def to_pair(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return [int(v[0]), int(v[1])]
        return None

    def clamp_step(v):
        if v > 1:
            return 1
        if v < -1:
            return -1
        return v

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def get_pos(obj):
        if obj is None:
            return None
        p = to_pair(obj)
        if p is not None:
            return p
        if isinstance(obj, dict):
            for k in ("pos", "position", "loc", "location", "xy", "coord", "coords", "agent_pos", "self_pos"):
                p = to_pair(obj.get(k))
                if p is not None:
                    return p
        return None

    def add_unique(lst, p):
        if p is None:
            return
        for q in lst:
            if q[0] == p[0] and q[1] == p[1]:
                return
        lst.append(p)

    def scan_pairs(x, out, depth=0):
        if depth > 4:
            return
        if isinstance(x, dict):
            p = get_pos(x)
            if p is not None:
                add_unique(out, p)
            for v in x.values():
                scan_pairs(v, out, depth + 1)
        elif isinstance(x, (list, tuple)):
            p = to_pair(x)
            if p is not None:
                add_unique(out, p)
            else:
                for v in x:
                    scan_pairs(v, out, depth + 1)

    obs = observation if isinstance(observation, dict) else {}

    me = None
    for k in ("agent_pos", "position", "pos", "location", "self_pos", "xy"):
        me = get_pos(obs.get(k))
        if me is not None:
            break

    if me is None:
        me = get_pos(obs.get("agent"))
    if me is None:
        me = get_pos(obs.get("self"))
    if me is None:
        me = [0, 0]

    goals = []
    threats = []
    friendlies = []

    for key in ("resources", "resource_positions", "food", "targets", "goal", "goals", "objective", "objectives",
                "capturable", "capture_points", "territories", "territory", "neutral", "unclaimed"):
        scan_pairs(obs.get(key), goals)

    for key in ("enemies", "enemy_positions", "opponents", "opponent_positions", "predators", "chasers"):
        scan_pairs(obs.get(key), threats)

    for key in ("allies", "teammates", "team", "friends"):
        scan_pairs(obs.get(key), friendlies)

    if "grid" in obs:
        grid = obs.get("grid")
        if isinstance(grid, (list, tuple)) and grid and isinstance(grid[0], (list, tuple)):
            for y, row in enumerate(grid):
                if not isinstance(row, (list, tuple)):
                    continue
                for x, cell in enumerate(row):
                    good = False
